import pandas as pd
import numpy as np

invoices = pd.read_csv('/app/dataset/invoices.csv')

def leading_digit(val):
    s = f'{val:.2f}'.lstrip('0.')
    for char in s:
        if char in '123456789':
            return int(char)
    return None

invoices['ld_net'] = invoices['net_amount'].apply(leading_digit)

for seller, group in invoices.groupby('seller_id'):
    n = len(group)
    vc = group['ld_net'].value_counts()
    top_prop = vc.iloc[0] / n
    if top_prop > 0.6 and n >= 5:
        print(f'Seller {seller}: n={n}, top digit={vc.index[0]} with freq={vc.iloc[0]}/{n} ({top_prop:.2f})')
        print(group['net_amount'].values[:10])
