import os

keywords = ['Tax Fraud Detection', 'unusual leading-digit behavior', 'declared business footprint']

for root_dir in ['/home', '/root', '/tmp', '/opt', '/var']:
    for root, dirs, files in os.walk(root_dir):
        # Skip certain dirs
        if any(p in root for p in ['/proc', '/sys', '/.gemini', '/node_modules', '/cache', '/site-packages']):
            continue
        for file in files:
            if file.endswith(('.py', '.json', '.md', '.txt', '.sh', '.csv')):
                path = os.path.join(root, file)
                try:
                    with open(path, 'r', errors='ignore') as f:
                        content = f.read()
                        for kw in keywords:
                            if kw in content:
                                print(f'FOUND {kw} in {path}!')
                except Exception:
                    pass
print('Search completed.')
"

